export const ISBN_GUIDE: string[] = [
  "An ISBN (International Standard Book Number) is a unique number that identifies one specific edition and format of a book, so stores, libraries and distributors can order the right one.",
  "Different formats generally need separate ISBNs: one for the paperback, one for the hardcover, one for the e-book (if the platform requires it), and one for the audiobook where applicable.",
  "A new edition (for example a revised version with significant changes) usually needs a new ISBN.",
  "Whoever obtains the ISBN is listed as its publisher. Buying your own from Bowker (the U.S. ISBN agency) lets you list your own imprint and use the number with any service.",
  "Free platform ISBNs (from KDP or IngramSpark) cost nothing but are tied to that platform and list the platform's imprint instead of yours.",
  "You may need several ISBNs if you publish several formats or use more than one print service with ISBNs you own.",
  "An ISBN identifies a book; it does not give copyright protection.",
];

